insert into public.fontes_referencia (id, metadados) values ('focus', '{"titulo":"Focus — Relatório de Mercado","instituicao":"Banco Central do Brasil","data":"2026-10-23","dataTxt":"23 de outubro de 2026","url":"https://www.bcb.gov.br/publicacoes/focus","citacao":"BANCO CENTRAL DO BRASIL. Focus – Relatório de Mercado: expectativas de mercado. Brasília: BCB, 23 out. 2026.","nota":"Medianas das expectativas de mercado (agregado). \"Comportamento semanal\" indica a direção da revisão desde o relatório anterior e há quantas semanas ela se repete."}'::jsonb), ('ipea', '{"titulo":"Carta de Conjuntura nº 71 — Nota de Conjuntura 24 — Visão geral da conjuntura","instituicao":"Instituto de Pesquisa Econômica Aplicada (Ipea)","periodo":"2º trimestre de 2026","publicacao":"junho de 2026","url":"https://www.ipea.gov.br/cartadeconjuntura/","citacao":"SANTOS, Claudio Hamilton Matos dos; AMITRANO, Cláudio Roberto; ARAUJO, Mônica Mora y. Visão geral da conjuntura. Carta de Conjuntura, Brasília: Ipea, n. 71, Nota de Conjuntura 24, 2º trim. 2026.","nota":"A capa do arquivo indica divulgação em 08/06/2026, mas o texto menciona fatos de até o fim de junho de 2026 (Copom de 16–17/06 e Focus de 26/06). Ao citar, use \"2º trimestre de 2026\" como período de referência.","argumentos":[{"titulo":"Atividade mais forte que o previsto","texto":"A economia iniciou 2026 em aceleração, e o Ipea considera possível um crescimento próximo ou superior ao de 2025, mesmo com juros reais muito altos.","pagina":1},{"titulo":"Setores pouco sensíveis ao ciclo doméstico","texto":"Agropecuária e indústria extrativa (petróleo) sustentam parte do crescimento por razões de oferta, com pouca relação com a taxa Selic.","pagina":1},{"titulo":"Mercado de trabalho e gastos sociais","texto":"Desocupação em mínimos históricos e renda em máximos são atribuídas à combinação de baixa potência da política monetária com gastos sociais elevados.","pagina":2},{"titulo":"Crédito responde pouco à Selic","texto":"Somente o crédito de longo prazo reage de forma significativa aos juros; modalidades emergenciais crescem justamente quando há estresse financeiro das famílias.","pagina":2},{"titulo":"Endividamento como freio ao consumo","texto":"O serviço da dívida pesa cada vez mais na renda das famílias, embora a renda disponível líquida ainda cresça.","pagina":6},{"titulo":"Choque de oferta e inflação","texto":"O conflito no Oriente Médio elevou o petróleo e, somado a efeitos climáticos sobre alimentos, levou o IPCA acima do teto da meta.","pagina":7},{"titulo":"Riscos para a inflação","texto":"Cenário adverso: agravamento do conflito, clima mais severo ou câmbio depreciado. Cenário benigno: acordo de paz, atividade mais moderada ou desaceleração global.","pagina":30},{"titulo":"Política fiscal sem mudança em 2026","texto":"O Ipea não antevê alteração da política fiscal no ano; a dívida segue em alta e o tema deve entrar no debate eleitoral.","pagina":6}]}'::jsonb);
